import XCTest
@testable import YaverTV

final class CredentialHandoffInteropTests: XCTestCase {
    func testDecryptsDeterministicTypeScriptNaClFixture() throws {
        // Generated by mobile/src/lib/credentialHandoff.ts with fixed keys and
        // nonce. Changing either implementation without the other breaks this.
        let envelope = CredentialHandoffEnvelope(
            version: 1, type: "yaver-credential-envelope", handoffId: "BwcHBwcHBwcHBwcHBwcHBwcH",
            targetDeviceId: "tv_interop_123", accountFingerprint: "j_yeIYsbK1OjVNewRnq1hAbr",
            senderPublicKey: "V9tLNZ8jrl4Ubk4lEgVnBHIlBjSMFQwUdT0Mkz0E1CE=",
            nonce: "BQUFBQUFBQUFBQUFBQUFBQUFBQUFBQUF",
            ciphertext: "")
        let secret = [UInt8](Data(base64Encoded: "AwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwMDAwM=")!)
        let payload = CredentialHandoff.decrypt(envelope: envelope, recipientSecretKey: secret)
        XCTAssertEqual(payload?.kind, "deepseek-api-key")
        XCTAssertEqual(payload?.value, "sk-interoperability-only")
        XCTAssertEqual(payload?.targetDeviceId, "tv_interop_123")
    }

    func testAccountFingerprintMatchesTypeScript() {
        XCTAssertEqual(CredentialHandoff.accountFingerprint("interop-account"), "j_yeIYsbK1OjVNewRnq1hAbr")
    }
}
